{
  "abilities": [
    {
      "advanced_exceptions": [
        {
          "citations": [
            {
              "quote": "Upon taking fatal damage, Anivia reverts to an egg and is reborn with full health.",
              "source_id": "riot:P"
            },
            {
              "quote": "Anivia enters resurrection for 6 seconds and restores all of her health.",
              "source_id": "wiki:P"
            },
            {
              "quote": "If Anivia remains alive by the end of the duration, she is revived with her current health.",
              "source_id": "wiki:P"
            }
          ],
          "status": "disputed",
          "summary": "Health timing differs in precision: Riot describes rebirth with full health; Wiki specifies full health upon entering resurrection and revival with remaining current health. Guaranteed full health upon completing resurrection is not established consistently."
        },
        {
          "citations": [
            {
              "quote": "While under resurrection, Anivia is unable to act and gains -40 – 20 (based on level) bonus armor and bonus magic resistance.",
              "source_id": "wiki:P"
            }
          ],
          "status": "supported",
          "summary": "During resurrection she cannot act, and her armor and magic resistance modifiers depend on level; these modifiers are not always positive."
        },
        {
          "citations": [
            {
              "quote": "Triggering Rebirth will break tethers on Anivia.",
              "source_id": "wiki:P"
            },
            {
              "quote": "Chronoshift and Guardian Angel will take priority over Rebirth.",
              "source_id": "wiki:P"
            },
            {
              "quote": "If Rebirth triggers while Anivia is channeling Teleport, her channel won't be interrupted.",
              "source_id": "wiki:P"
            },
            {
              "quote": "All other channels will be interrupted upon triggering Rebirth.",
              "source_id": "wiki:P"
            }
          ],
          "status": "supported",
          "summary": "Rebirth breaks tethers, yields priority to Chronoshift and Guardian Angel, and interrupts channels except Teleport."
        }
      ],
      "core_mechanics": [
        {
          "citations": [
            {
              "quote": "Upon taking fatal damage, Anivia reverts to an egg",
              "source_id": "riot:P"
            },
            {
              "quote": "Periodically, upon dying, Anivia will instead revert into an egg.",
              "source_id": "wiki:P"
            }
          ],
          "id": "P.egg",
          "summary": "When available, fatal damage turns Anivia into an egg instead of immediately killing her."
        },
        {
          "citations": [
            {
              "quote": "If the egg can survive for a few seconds, she is gloriously reborn.",
              "source_id": "wiki:P"
            },
            {
              "quote": "If Anivia remains alive by the end of the duration, she is revived with her current health.",
              "source_id": "wiki:P"
            }
          ],
          "id": "P.revive",
          "summary": "She revives if the egg survives the resurrection period."
        }
      ],
      "slot": "P",
      "unsupported_claims": [
        "The egg is invulnerable or revival is guaranteed.",
        "Resurrection always grants increased defenses.",
        "Anivia is guaranteed full health when resurrection completes."
      ]
    },
    {
      "advanced_exceptions": [
        {
          "citations": [
            {
              "quote": "Recast: Anivia shatters the ice, dealing magic damage to nearby enemies and stunning them for a duration, as well as refreshing the slow.",
              "source_id": "wiki:Q"
            }
          ],
          "status": "supported",
          "summary": "The explosion also refreshes the slow."
        },
        {
          "citations": [
            {
              "quote": "Spell shield can block the effects of either the active or the recast, but not both if the former is blocked.",
              "source_id": "wiki:Q"
            }
          ],
          "status": "supported",
          "summary": "A spell shield can block the initial pass or explosion, but blocking the initial pass does not also block the explosion."
        },
        {
          "citations": [
            {
              "quote": "The initial cast and the manual recast count as ability activations for the purposes of on-cast effects such as Spellblade and triggering Force Pulse's passive.",
              "source_id": "wiki:Q"
            },
            {
              "quote": "If the ability is not manually recasted, the secondary effect will trigger without being considered as an ability activation.",
              "source_id": "wiki:Q"
            },
            {
              "quote": "Flash Frost will fire from wherever Anivia was at the start of the cast time.",
              "source_id": "wiki:Q"
            }
          ],
          "status": "supported",
          "summary": "Manual recasting counts as an ability activation; automatic detonation does not. The projectile originates from her position at cast start."
        }
      ],
      "core_mechanics": [
        {
          "citations": [
            {
              "quote": "chilling and damaging anyone in its path",
              "source_id": "riot:Q"
            },
            {
              "quote": "Anivia launches a chunk of ice that deals magic damage and slows enemies hit.",
              "source_id": "wiki:Q"
            }
          ],
          "id": "Q.projectile",
          "summary": "Launches an ice projectile that damages and slows enemies along its path."
        },
        {
          "citations": [
            {
              "quote": "When the sphere explodes it does moderate damage in a radius, stunning anyone in the area.",
              "source_id": "riot:Q"
            },
            {
              "quote": "Recast: The ice explodes, dealing magic damage and stunning nearby enemies.",
              "source_id": "wiki:Q"
            }
          ],
          "id": "Q.explosion",
          "summary": "The projectile explodes to damage and stun nearby enemies."
        },
        {
          "citations": [
            {
              "quote": "Flash Frost can be recast while the ice is in flight after its cast time, and does so automatically at maximum range.",
              "source_id": "wiki:Q"
            }
          ],
          "id": "Q.recast",
          "summary": "Can be recast during flight to explode early; otherwise it explodes at maximum range."
        }
      ],
      "slot": "Q",
      "unsupported_claims": [
        "The projectile stops at the first enemy hit.",
        "The initial projectile pass itself stuns.",
        "A spell shield blocking the initial pass also blocks the explosion."
      ]
    },
    {
      "advanced_exceptions": [
        {
          "citations": [
            {
              "quote": "Anivia summons a wall of ice at the target location perpendicular to her facing, knocking all units away from it, though not through terrain.",
              "source_id": "wiki:W"
            }
          ],
          "status": "supported",
          "summary": "The wall appears perpendicular to Anivia's facing and displaces units at its placement, without knocking them through terrain."
        },
        {
          "citations": [
            {
              "quote": "Crystallize's displacement triggers in-combat effects by dealing 0 proc true damage, such as drawing turret aggro, Sudden Impact and applying Elixir of Sorcery.",
              "source_id": "wiki:W"
            },
            {
              "quote": "Player-generated terrain such as Crystallize does not block sight.",
              "source_id": "wiki:W"
            }
          ],
          "status": "supported",
          "summary": "Its displacement can trigger combat effects through zero proc true damage. The wall does not block sight."
        },
        {
          "citations": [
            {
              "quote": "PENDING FOR TEST: Knockback speed?",
              "source_id": "wiki:W"
            }
          ],
          "status": "uncertain",
          "summary": "Knockback speed is explicitly pending testing and is not established."
        }
      ],
      "core_mechanics": [
        {
          "citations": [
            {
              "quote": "Anivia condenses the moisture in the air into an impassable wall of ice to block all movement.",
              "source_id": "riot:W"
            },
            {
              "quote": "The wall lingers as impassable terrain for 5 seconds.",
              "source_id": "wiki:W"
            }
          ],
          "id": "W.terrain",
          "summary": "Creates an ice wall that blocks movement through its terrain."
        },
        {
          "citations": [
            {
              "quote": "The wall only lasts a short duration before it melts.",
              "source_id": "riot:W"
            },
            {
              "quote": "Anivia erects a wall of ice that lingers for a few seconds, blocking movement.",
              "source_id": "wiki:W"
            }
          ],
          "id": "W.temporary",
          "summary": "The wall is temporary and disappears after a short duration."
        }
      ],
      "slot": "W",
      "unsupported_claims": [
        "The wall blocks projectiles.",
        "The wall blocks vision.",
        "Every dash, blink, or other movement ability is prevented from crossing the wall.",
        "The pending knockback speed has been verified."
      ]
    },
    {
      "advanced_exceptions": [
        {
          "citations": [
            {
              "quote": "Enemies hit by Flash Frost or a fully formed Glacial Storm become Iced for 3 seconds, refreshing on subsequent hits.",
              "source_id": "wiki:E"
            },
            {
              "quote": "The damage of Frostbite is calculated once it hits. If the target's mark from being hit by Flash Frost or a fully formed Glacial Storm wears off while the projectile is traveling, the damage is not doubled.",
              "source_id": "wiki:E"
            }
          ],
          "status": "supported",
          "summary": "The Iced mark lasts three seconds and refreshes on qualifying hits. Double damage is determined on impact, so a mark expiring during travel prevents the bonus."
        },
        {
          "citations": [
            {
              "quote": "If the target becomes untargetable, dies, or is too far away or no longer in sight during the cast time, this ability will cancel but does not go on cooldown nor pay its cost (if applicable).",
              "source_id": "wiki:E"
            }
          ],
          "status": "supported",
          "summary": "Specified target invalidations during cast time cancel Frostbite without spending its cost or triggering its cooldown."
        }
      ],
      "core_mechanics": [
        {
          "citations": [
            {
              "quote": "Anivia blasts a freezing gust of wind at her target, dealing damage.",
              "source_id": "riot:E"
            },
            {
              "quote": "Anivia blasts a freezing wind at the target enemy that deals magic damage",
              "source_id": "wiki:E"
            }
          ],
          "id": "E.targeted_damage",
          "summary": "Deals magic damage to a targeted enemy."
        },
        {
          "citations": [
            {
              "quote": "If the target was recently hit by Flash Frost or damaged by a fully formed Glacial Storm, the damage they take is doubled.",
              "source_id": "riot:E"
            },
            {
              "quote": "Enemies hit by Flash Frost or a fully formed Glacial Storm become Iced for 3 seconds, refreshing on subsequent hits.",
              "source_id": "wiki:E"
            },
            {
              "quote": "doubled if they were Iced",
              "source_id": "wiki:E"
            }
          ],
          "id": "E.double_damage",
          "summary": "Deals double damage to enemies recently hit by Flash Frost or a fully formed Glacial Storm."
        }
      ],
      "slot": "E",
      "unsupported_claims": [
        "Any slow or ice-themed ability enables double damage.",
        "Glacial Storm before it fully forms enables double damage.",
        "Casting Frostbite while the mark is active guarantees double damage even if the mark expires before impact."
      ]
    },
    {
      "advanced_exceptions": [
        {
          "citations": [
            {
              "quote": "Passive: Flash Frost's slow strength is increased.",
              "source_id": "wiki:R"
            }
          ],
          "status": "supported",
          "summary": "Glacial Storm also increases Flash Frost's slow strength."
        },
        {
          "citations": [
            {
              "quote": "Toggling Glacial Storm off triggers a final tick of damage and incurs its full cooldown.",
              "source_id": "wiki:R"
            },
            {
              "quote": "Glacial Storm is toggled off automatically if Anivia moves too far away from the blizzard or becomes unable to pay the mana cost, or is affected by any form of cast-inhibiting crowd control.",
              "source_id": "wiki:R"
            }
          ],
          "status": "supported",
          "summary": "Turning the storm off deals a final damage tick. Excessive distance, insufficient mana, or cast-inhibiting crowd control automatically ends it."
        },
        {
          "citations": [
            {
              "quote": "Stasis via Zhonya's Hourglass doesn't interrupt Glacial Storm.",
              "source_id": "wiki:R"
            },
            {
              "quote": "Tahm Kench's Devour does interrupt (allied and enemy) Glacial Storm.",
              "source_id": "wiki:R"
            },
            {
              "quote": "Glacial Storm's slow leaves a trail that is visible even if the target is stealthed.",
              "source_id": "wiki:R"
            }
          ],
          "status": "supported",
          "summary": "Zhonya's stasis preserves the storm, while allied or enemy Devour interrupts it. Its slow leaves a visible trail even on stealthed targets."
        }
      ],
      "core_mechanics": [
        {
          "citations": [
            {
              "quote": "Toggle: Anivia summons a driving rain of ice and hail at the target location",
              "source_id": "wiki:R"
            }
          ],
          "id": "R.toggle",
          "summary": "Toggles a persistent storm at a target location."
        },
        {
          "citations": [
            {
              "quote": "Anivia summons a driving rain of ice and hail to damage her enemies and slow their advance.",
              "source_id": "riot:R"
            },
            {
              "quote": "continually deals magic damage and slows enemies within",
              "source_id": "wiki:R"
            }
          ],
          "id": "R.damage_slow",
          "summary": "Repeatedly damages and slows enemies inside the storm."
        },
        {
          "citations": [
            {
              "quote": "The blizzard increases in size over 1.5 seconds. At maximum size, Glacial Storm is empowered to deal 300% damage and increase the effectiveness of its slow by 50%",
              "source_id": "wiki:R"
            }
          ],
          "id": "R.growth",
          "summary": "Grows after activation; at full size it deals more damage and applies a stronger slow."
        }
      ],
      "slot": "R",
      "unsupported_claims": [
        "The storm follows Anivia.",
        "Anivia must remain inside the storm to maintain it.",
        "Every disable interrupts the storm.",
        "The visible slow trail grants true sight or makes stealthed enemies targetable."
      ]
    }
  ]
}
